-- NovaCart database. Import this file in phpMyAdmin before opening the site.
CREATE DATABASE IF NOT EXISTS ecommerce_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ecommerce_db;
CREATE TABLE admin(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
-- The setup password is admin123; it is upgraded to a password hash at the first successful admin sign-in.
INSERT INTO admin(name,email,password) VALUES('Store Administrator','admin@gmail.com','admin123');
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,phone VARCHAR(30) NOT NULL,address TEXT NOT NULL,password VARCHAR(255) NOT NULL,blocked TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,icon VARCHAR(40) DEFAULT 'tag');
INSERT INTO categories(name,icon) VALUES ('Electronics','headphones'),('Fashion','shirt'),('Shoes','shoe-prints'),('Watches','clock'),('Mobile','mobile-screen'),('Laptop','laptop'),('Home Appliances','house'),('Grocery','basket-shopping'),('Beauty','wand-magic-sparkles'),('Sports','dumbbell');
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,category_id INT NOT NULL,price DECIMAL(10,2) NOT NULL,discount_price DECIMAL(10,2) NULL,stock INT NOT NULL DEFAULT 0,description TEXT NOT NULL,image VARCHAR(255) NOT NULL,rating DECIMAL(2,1) DEFAULT 4.5,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT);
INSERT INTO products(name,category_id,price,discount_price,stock,description,image,rating) VALUES
('iPhone 15',5,79999,74999,20,'A bright, powerful smartphone built for daily creativity.','images/products/iphone.svg',4.8),('Samsung Galaxy S24',5,74999,69999,18,'Premium Android performance with an exceptional camera.','images/products/galaxy.svg',4.7),('HP Pavilion Laptop',6,65999,59999,12,'Reliable performance for work, study and play.','images/products/laptop.svg',4.6),('Nike Air Runner',3,8999,6999,30,'Responsive everyday trainers with a clean athletic silhouette.','images/products/shoes.svg',4.5),('Apple Watch SE',4,32999,29999,25,'Your essential health and fitness companion.','images/products/watch.svg',4.8),('Sony WH Headphones',1,24999,19999,15,'Immersive wireless noise cancellation for every commute.','images/products/headphones.svg',4.7),('Canon EOS Camera',1,57999,52999,9,'Capture sharp memories with this versatile camera.','images/products/camera.svg',4.6),('RGB Gaming Keyboard',1,6999,4999,32,'Tactile keys and vivid lighting for your desk setup.','images/products/keyboard.svg',4.5),('JBL Bluetooth Speaker',1,8999,7499,40,'Room-filling portable sound with all-day battery.','images/products/speaker.svg',4.6),('4K Smart TV',7,49999,44999,10,'Cinematic 4K entertainment in a slim modern design.','images/products/tv.svg',4.7);
CREATE TABLE cart(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_cart(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(30) NOT NULL UNIQUE,user_id INT NOT NULL,address TEXT NOT NULL,phone VARCHAR(30) NOT NULL,city VARCHAR(80) NOT NULL,state VARCHAR(80) NOT NULL,pincode VARCHAR(15) NOT NULL,payment_method VARCHAR(50) NOT NULL,subtotal DECIMAL(10,2) NOT NULL,gst DECIMAL(10,2) NOT NULL,shipping DECIMAL(10,2) NOT NULL,total DECIMAL(10,2) NOT NULL,status ENUM('Pending','Processing','Shipped','Delivered','Cancelled') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,product_name VARCHAR(180) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT);
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,method VARCHAR(50) NOT NULL,amount DECIMAL(10,2) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
